"""Random strings mixing letters (both cases), digits and punctuation."""

import string

ALPHABET = string.ascii_letters + string.digits + " .,!?-'\""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    n = rng.randint(0, 40)
    text = "".join(rng.choice(ALPHABET) for _ in range(n))
    return {"name": "a random %d-character string #%d" % (n, index),
            "stdin": text + "\n"}
